EXPECTED_PNG_SHA256 = "fa56b296bd171d627178e68d79fefb89d97fe4ba76f345b628df518fc0136836"
EXPECTED_RGBA_SHA256 = "3c19277ca491eacf284f48c7f5215783f4102e375d35347a8cc57b79e77c046e"
EXPECTED_RGBA_BYTES = 320 * 240 * 4


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 anchor, found {count}")
    return text.replace(old, new, 1)


def regex_once(text: str, pattern: str, replacement, label: str, flags: int = 0) -> str:
    result, count = re.subn(pattern, replacement, text, count=1, flags=flags)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 match, found {count}")
    return result


def split_bottom_function(text: str) -> tuple[str, str, str]:
    start_marker = "static void AvP3DS_DrawBottomFrame(void)"
    end_marker = "\nvoid AvP3DS_GameFrameEnd(void)"

    start = text.find(start_marker)
    if start < 0:
        raise RuntimeError("AvP3DS_DrawBottomFrame start not found")

    end = text.find(end_marker, start)
    if end < 0:
        raise RuntimeError("AvP3DS_DrawBottomFrame end not found")

    return text[:start], text[start:end], text[end:]


def main() -> int:
    root = Path.cwd().resolve()
    main_path = root / "src" / "main_3ds.c"

    if not main_path.is_file() or not (root / "Makefile.3ds").is_file():
        print("ERROR: run this from C:/Projects/AvP3DS/Source")
        print("Nothing changed.")
        return 1

    original = main_path.read_text(encoding="utf-8")

    if MARKER in original:
        print("ERROR: Predator native backdrop patch is already installed.")
        print("Nothing changed.")
        return 1

    for required in ("AVP-HUD1F", "AVP-HUD1G1", "PRED-HUD1A-SPECIES-ISOLATED"):
        if required not in original:
            print(f"ERROR: required baseline marker missing: {required}")
            print("Nothing changed.")
            return 1

    marine_entries = (
        "{ 84.0f, 36.0f, 144.0f, 88.0f, 1.35f }",
        "{ 10.0f, 124.0f, 86.0f, 78.0f, 1.00f }",
        "{ 208.0f, 124.0f, 112.0f, 78.0f, 0.82f }",
        "{ 40.0f, 0.0f, 240.0f, 32.0f, 0.86f }",
    )

    for entry in marine_entries:
        if original.count(entry) != 1:
            print(f"ERROR: sealed Marine layout entry missing or duplicated: {entry}")
            print("Nothing changed.")
            return 1

    try:
        png_bytes = zlib.decompress(base64.b64decode(PNG_ZLIB_B64))
        rgba_bytes = zlib.decompress(base64.b64decode(RGBA_ZLIB_B64))
    except Exception as exc:
        print(f"ERROR: embedded asset decode failed: {exc}")
        print("Nothing changed.")
        return 1

    if len(rgba_bytes) != EXPECTED_RGBA_BYTES:
        print(
            f"ERROR: embedded RGBA size is {len(rgba_bytes)}, "
            f"expected {EXPECTED_RGBA_BYTES}"
        )
        print("Nothing changed.")
        return 1

    if sha256(png_bytes) != EXPECTED_PNG_SHA256:
        print("ERROR: embedded PNG hash verification failed.")
        print("Nothing changed.")
        return 1

    if sha256(rgba_bytes) != EXPECTED_RGBA_SHA256:
        print("ERROR: embedded RGBA hash verification failed.")
        print("Nothing changed.")
        return 1

    text = original

    try:
        globals_anchor = """/* AVP-HUD1D native Citro3D Marine backdrop. */
static C3D_Tex avp3ds_marine_hud_texture;
static bool avp3ds_marine_hud_texture_initialized = false;
"""

        globals_replacement = globals_anchor + f"""
/* {MARKER}: independent Predator lower-screen backdrop. */
static C3D_Tex avp3ds_predator_hud_texture;
static bool avp3ds_predator_hud_texture_initialized = false;
"""

        text = replace_once(
            text,
            globals_anchor,
            globals_replacement,
            "Predator texture globals",
        )

        loader_insert_anchor = """static unsigned int AvP3DS_NextPowerOfTwo(
    unsigned int value)
"""

        predator_loader = f"""/*
 * {MARKER}.
 *
 * Deliberately separate from the sealed Marine texture lifecycle.
 * The asset shares the same 320x240 source and 512x256 PICA texture sizes.
 */
static bool AvP3DS_LoadPredatorHUDTexture(void)
{{
    FILE *file;
    unsigned char *pixels;
    size_t bytesRead;
    unsigned int y;

    memset(
        &avp3ds_predator_hud_texture,
        0,
        sizeof(avp3ds_predator_hud_texture));

    file = fopen(
        "romfs:/Predator_HUD_Backdrop_320x240.rgba",
        "rb");

    if (file == NULL)
    {{
        printf("Predator HUD raw backdrop was not found.\\n");
        return false;
    }}

    pixels = malloc(AVP3DS_MARINE_HUD_RAW_BYTES);

    if (pixels == NULL)
    {{
        fclose(file);
        printf("Predator HUD raw backdrop allocation failed.\\n");
        return false;
    }}

    bytesRead = fread(
        pixels,
        1,
        AVP3DS_MARINE_HUD_RAW_BYTES,
        file);

    fclose(file);

    if (bytesRead != AVP3DS_MARINE_HUD_RAW_BYTES)
    {{
        free(pixels);
        printf(
            "Predator HUD raw backdrop was truncated: %lu bytes.\\n",
            (unsigned long)bytesRead);
        return false;
    }}

    if (!C3D_TexInit(
            &avp3ds_predator_hud_texture,
            AVP3DS_MARINE_HUD_TEXTURE_WIDTH,
            AVP3DS_MARINE_HUD_TEXTURE_HEIGHT,
            GPU_RGBA8))
    {{
        free(pixels);
        printf("Predator HUD native texture initialization failed.\\n");
        return false;
    }}

    avp3ds_predator_hud_texture_initialized = true;

    C3D_TexSetFilter(
        &avp3ds_predator_hud_texture,
        GPU_NEAREST,
        GPU_NEAREST);

    C3D_TexSetWrap(
        &avp3ds_predator_hud_texture,
        GPU_CLAMP_TO_EDGE,
        GPU_CLAMP_TO_EDGE);

    memset(
        avp3ds_predator_hud_texture.data,
        0,
        avp3ds_predator_hud_texture.size);

    for (y = 0;
         y < AVP3DS_MARINE_HUD_SOURCE_HEIGHT;
         ++y)
    {{
        unsigned int x;

        for (x = 0;
             x < AVP3DS_MARINE_HUD_SOURCE_WIDTH;
             ++x)
        {{
            const unsigned char *sourcePixel =
                pixels +
                (((size_t)y *
                  AVP3DS_MARINE_HUD_SOURCE_WIDTH +
                  x) * 4U);

            unsigned char *destinationPixel =
                (unsigned char *)
                    avp3ds_predator_hud_texture.data +
                AvP3DS_TiledOffsetForWidth(
                    AVP3DS_MARINE_HUD_TEXTURE_WIDTH,
                    x,
                    y) * 4U;

            /* CPU RGBA -> PICA RGBA8 byte order A, B, G, R. */
            destinationPixel[0] = sourcePixel[3];
            destinationPixel[1] = sourcePixel[2];
            destinationPixel[2] = sourcePixel[1];
            destinationPixel[3] = sourcePixel[0];
        }}
    }}

    free(pixels);

    GSPGPU_FlushDataCache(
        avp3ds_predator_hud_texture.data,
        avp3ds_predator_hud_texture.size);

    return true;
}}

"""

        text = replace_once(
            text,
            loader_insert_anchor,
            predator_loader + loader_insert_anchor,
            "Predator texture loader insertion",
        )

        marine_load_block = """    if (!AvP3DS_LoadMarineHUDTexture())
    {
        printf(
            "Marine HUD native backdrop unavailable; "
            "keeping diagnostic grid.\\n");
    }
"""

        predator_load_block = marine_load_block + """\n    if (!AvP3DS_LoadPredatorHUDTexture())
    {
        printf(
            "Predator HUD native backdrop unavailable; "
            "keeping diagnostic grid.\\n");
    }
"""

        text = replace_once(
            text,
            marine_load_block,
            predator_load_block,
            "Predator texture load block",
        )

        cleanup_anchor = """    if (avp3ds_marine_hud_texture_initialized)
    {
        C3D_TexDelete(&avp3ds_marine_hud_texture);
        memset(
            &avp3ds_marine_hud_texture,
            0,
            sizeof(avp3ds_marine_hud_texture));
        avp3ds_marine_hud_texture_initialized = false;
    }
"""

        cleanup_replacement = cleanup_anchor + f"""
    /* {MARKER}: Predator texture cleanup is independent. */
    if (avp3ds_predator_hud_texture_initialized)
    {{
        C3D_TexDelete(&avp3ds_predator_hud_texture);
        memset(
            &avp3ds_predator_hud_texture,
            0,
            sizeof(avp3ds_predator_hud_texture));
        avp3ds_predator_hud_texture_initialized = false;
    }}
"""

        text = replace_once(
            text,
            cleanup_anchor,
            cleanup_replacement,
            "Predator texture cleanup",
        )

        before, bottom, after = split_bottom_function(text)

        existing_condition = (
            "if (!predatorHUDCaptured && "
            "avp3ds_marine_hud_texture_initialized)"
        )

        if bottom.count(existing_condition) != 2:
            raise RuntimeError(
                "DrawBottomFrame existing species conditions: "
                f"expected 2, found {bottom.count(existing_condition)}"
            )

        first = bottom.find(existing_condition)
        first_replacement = (
            "if ((predatorHUDCaptured && "
            "avp3ds_predator_hud_texture_initialized) ||\n"
            "        (!predatorHUDCaptured && "
            "avp3ds_marine_hud_texture_initialized))"
        )
        bottom = (
            bottom[:first]
            + first_replacement
            + bottom[first + len(existing_condition):]
        )

        marine_bind_block = """if (!predatorHUDCaptured && avp3ds_marine_hud_texture_initialized)
    {
        C3D_TexBind(
            0,
            &avp3ds_marine_hud_texture);

        C3D_TexEnvSrc(
            textureEnvironment,
            C3D_Both,
            GPU_TEXTURE0,
            GPU_PRIMARY_COLOR,
            0);

        C3D_TexEnvFunc(
            textureEnvironment,
            C3D_Both,
            GPU_MODULATE);
    }
    else
"""

        predator_marine_bind_block = """if (predatorHUDCaptured &&
        avp3ds_predator_hud_texture_initialized)
    {
        C3D_TexBind(
            0,
            &avp3ds_predator_hud_texture);

        C3D_TexEnvSrc(
            textureEnvironment,
            C3D_Both,
            GPU_TEXTURE0,
            GPU_PRIMARY_COLOR,
            0);

        C3D_TexEnvFunc(
            textureEnvironment,
            C3D_Both,
            GPU_MODULATE);
    }
    else if (!predatorHUDCaptured &&
             avp3ds_marine_hud_texture_initialized)
    {
        C3D_TexBind(
            0,
            &avp3ds_marine_hud_texture);

        C3D_TexEnvSrc(
            textureEnvironment,
            C3D_Both,
            GPU_TEXTURE0,
            GPU_PRIMARY_COLOR,
            0);

        C3D_TexEnvFunc(
            textureEnvironment,
            C3D_Both,
            GPU_MODULATE);
    }
    else
"""

        bottom = replace_once(
            bottom,
            marine_bind_block,
            predator_marine_bind_block,
            "Predator/Marine texture bind routing",
        )

        text = before + bottom + after

        for entry in marine_entries:
            if text.count(entry) != 1:
                raise RuntimeError(
                    f"Marine layout changed during patch: {entry}"
                )

        for required in ("AVP-HUD1F", "AVP-HUD1G1"):
            if required not in text:
                raise RuntimeError(f"Marine marker lost: {required}")

        if text.count("romfs:/Marine_WY_HUD.rgba") != 1:
            raise RuntimeError("Marine asset path changed or duplicated")

        if text.count("romfs:/Predator_HUD_Backdrop_320x240.rgba") != 1:
            raise RuntimeError("Predator asset path verification failed")

        if text.count(MARKER) < 4:
            raise RuntimeError("Predator backdrop marker verification failed")

    except Exception as exc:
        print(f"ERROR: {exc}")
        print("Nothing changed.")
        return 1

    backup = main_path.with_name("main_3ds.c.pre-PRED-HUD1C2-BACKDROP.bak")
    romfs_dir = root / "romfs"
    assets_dir = root / "assets"
    raw_out = romfs_dir / "Predator_HUD_Backdrop_320x240.rgba"
    png_out = assets_dir / "Predator_HUD_Backdrop_320x240.png"

    if backup.exists():
        print(f"ERROR: backup already exists: {backup}")
        print("Nothing changed.")
        return 1

    if raw_out.exists() or png_out.exists():
        print("ERROR: Predator backdrop asset already exists.")
        print(f"  {raw_out}")
        print(f"  {png_out}")
        print("Nothing changed.")
        return 1

    romfs_dir.mkdir(parents=True, exist_ok=True)
    assets_dir.mkdir(parents=True, exist_ok=True)
    shutil.copy2(main_path, backup)

    wrote_raw = False
    wrote_png = False

    try:
        raw_out.write_bytes(rgba_bytes)
        wrote_raw = True

        png_out.write_bytes(png_bytes)
        wrote_png = True

        main_path.write_text(text, encoding="utf-8")
    except Exception as exc:
        shutil.copy2(backup, main_path)

        if wrote_raw and raw_out.exists():
            raw_out.unlink()
        if wrote_png and png_out.exists():
            png_out.unlink()

        print(f"ERROR while writing: {exc}")
        print("main_3ds.c was restored and new assets were removed.")
        return 1

    print("PRED-HUD1C2 native Predator backdrop installed.")
    print(f"Backup: {backup}")
    print(f"RomFS:  {raw_out}")
    print(f"Asset:  {png_out}")
    print(f"RGBA SHA-256: {sha256(rgba_bytes)}")
    print()
    print("Species routing:")
    print("  Marine   -> existing Marine texture and path")
    print("  Predator -> new Predator texture")
    print("  Fallback -> existing diagnostic behavior")
    return 0


if __name__ == "__main__":
    sys.exit(main())
